local function _bxor(a, b)
    a = math.floor(tonumber(a) or 0) % 256
    b = math.floor(tonumber(b) or 0) % 256
    if bit32 and bit32.bxor then
        return bit32.band(bit32.bxor(a, b), 255)
    end
    local r, bit = 0, 1
    while a > 0 or b > 0 do
        local a1, b1 = a % 2, b % 2
        if a1 ~= b1 then r = r + bit end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        bit = bit * 2
    end
    return r % 256
end

local function _dec()
    local flat = {}
    for i = 1, #_c do
        local ch = _c[i]
        for j = 1, #ch do
            flat[#flat + 1] = ch[j]
        end
    end
    local parts = {}
    local kl = #_k
    for i = 1, #flat do
        local kb = string.byte(_k, ((i - 1) % kl) + 1)
        local v = _bxor(flat[i], kb)
        parts[i] = string.char(v)
    end
    return table.concat(parts)
end

print("[HellObfuscation] decrypting...")
local src = _dec()
print("[HellObfuscation] loading...", #src, "chars")
local fn, err = loadstring(src)
if not fn then
    fn, err = load(src)
end
if not fn then
    error("[HellObfuscation] load failed: " .. tostring(err), 0)
end
print("[HellObfuscation] running...")
fn()
print("[HellObfuscation] done")
